final class CaseMaterialRequestsTabController {
    private static final Logger LOG=LoggerFactory.getLogger(CaseMaterialRequestsTabController.class); private static final DateTimeFormatter F=DateTimeFormatter.ofPattern("MMM d, yyyy h:mm a");
    private final ExecutorService ex=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"case-material-requests-worker");t.setDaemon(true);return t;}); private final AtomicInteger gen=new AtomicInteger(); private final AtomicBoolean saving=new AtomicBoolean();
    private MaterialRequestServicePort svc; private AppState state; private Supplier<Long> caseId; private Supplier<Window> owner; private VBox root,list; private Label title,status; private boolean loaded;
    void init(MaterialRequestServicePort s, AppState a, Supplier<Long> c, Supplier<Window> o){svc=s;state=a;caseId=c;owner=o;}
    Node view(){ if(root!=null)return root; list=new VBox(10); title=title("Material Requests"); status=muted("Loading material requests…"); Button add=primary("New Request"); add.setOnAction(e->openEditor(null)); root=new VBox(10,section(title,add,status,list)); root.setPadding(new Insets(8)); root.getStyleClass().add("case-main-surface"); return root; }
    void load(){ if(!loaded) refresh(); } void refresh(){ long cid=cid(); int tid=tenant(); int g=gen.incrementAndGet(); show(status,"Loading material requests…"); list.getChildren().clear(); runRead("list-material-requests",()->svc.listMaterialRequests(cid,tid), rows->{ if(stale(g,cid))return; loaded=true; render(rows==null?List.of():rows);}, "Material requests could not be loaded."); }
    private void render(List<MaterialRequestSummaryDto> rows){ var sorted=rows.stream().sorted(Comparator.comparing((MaterialRequestSummaryDto r)->terminal(r.status())).thenComparing(r->Optional.ofNullable(r.nextFollowUpAt()).orElse(Optional.ofNullable(r.expectedResponseDate()).orElse(LocalDateTime.MAX))).thenComparingLong(MaterialRequestSummaryDto::id)).toList(); title.setText("Material Requests ("+sorted.size()+")"); list.getChildren().clear(); if(sorted.isEmpty())show(status,"No material requests yet."); else {hide(status); sorted.forEach(r->list.getChildren().add(card(r)));}}
    private Node card(MaterialRequestSummaryDto r){ VBox b=MaterialsUi.card(); b.getChildren().addAll(strong(nvl(r.title(),r.materialTypeName())), pill("Status: "+nvl(r.status(),"Unknown")), line("From",source(r.requestedFromContactDisplayName(),r.requestedFromOrganizationName(),r.requestedFromText())), line("Assigned",nvl(r.assignedToDisplayName(),"Unassigned")), line("Requested / Due / Follow-up",fmt(r.requestedAt())+" • Due "+fmt(r.expectedResponseDate())+" • Next "+fmt(r.nextFollowUpAt()))); b.setOnMouseClicked(e->openDetail(r.id())); return b; }
    private void openDetail(long id){ long c=cid(); int t=tenant(), a=actor(); runRead("get-material-request",()->svc.getMaterialRequest(c,id,t,a).orElseThrow(),this::detail,"Material request could not be loaded."); }
    private void detail(MaterialRequestDetailDto d){ Dialog<Void> dlg=dialog("Material Request"); VBox c=new VBox(10,strong(nvl(d.title(),d.materialTypeName())),line("Status",nvl(d.status(),"Unknown")),line("Source",source(d.requestedFromContactDisplayName(),d.requestedFromOrganizationName(),d.requestedFromText())),line("Dates",fmt(d.requestedAt())+" • Due "+fmt(d.expectedResponseDate())+" • Follow-up "+fmt(d.nextFollowUpAt())),text("Description",d.description()),text("Notes",d.notes())); ButtonType follow=new ButtonType("Record Follow-up"), edit=new ButtonType("Edit"), statusBt=new ButtonType("Change Status"), del=new ButtonType("Delete", ButtonBar.ButtonData.LEFT); dlg.getDialogPane().getButtonTypes().addAll(follow,edit,statusBt,del,ButtonType.CLOSE); dlg.getDialogPane().setContent(new ScrollPane(c)); button(dlg,follow,()->follow(d)); button(dlg,edit,()->openEditor(d)); button(dlg,statusBt,()->changeStatus(d)); button(dlg,del,()->delete(d)); dlg.showAndWait(); }
    private void openEditor(MaterialRequestDetailDto e){ MaterialRequestForm f=new MaterialRequestForm(e, svc.listEffectiveMaterialTypes(tenant()), actor()); Optional<MaterialRequestForm.Values> v=f.showAndWait(); v.ifPresent(x->mutate(()-> e==null?svc.createMaterialRequest(x.create(tenant(),actor(),cid())):svc.updateMaterialRequest(x.update(tenant(),actor(),cid(),e.id(),e.rowVer())), this::refresh, "Material request saved.")); }
    private void follow(MaterialRequestDetailDto d){ TextInputDialog t=new TextInputDialog(); t.setTitle("Record Follow-up"); t.setHeaderText("Append-only follow-up history. Existing follow-ups cannot be edited or deleted."); t.showAndWait().ifPresent(note->mutate(()->svc.recordFollowUp(new MaterialRequestServicePort.RecordMaterialRequestFollowUpCommand(tenant(),actor(),cid(),d.id(),LocalDateTime.now(),actor(),"PHONE","NO_RESPONSE",d.nextFollowUpAt(),trim(note),d.rowVer())),this::refresh,"Follow-up recorded."));}
    private void changeStatus(MaterialRequestDetailDto d){ ChoiceDialog<String> c=new ChoiceDialog<>(d.status(),List.of("DRAFT","REQUESTED","FOLLOW_UP_DUE","PARTIALLY_RECEIVED","FULLY_RECEIVED","CLOSED","CANCELLED")); c.setTitle("Change Request Status"); c.showAndWait().ifPresent(s->mutate(()->svc.changeMaterialRequestStatus(new MaterialRequestServicePort.ChangeMaterialRequestStatusCommand(tenant(),actor(),cid(),d.id(),s,d.requestedAt(),d.firstReceivedAt(),d.fullyReceivedAt(),LocalDateTime.now(),actor(),d.closureReason(),d.rowVer())),this::refresh,"Request status changed."));}
    private void delete(MaterialRequestDetailDto d){ mutate(()->{svc.deleteMaterialRequest(new MaterialRequestServicePort.DeleteMaterialRequestCommand(tenant(),actor(),cid(),d.id(),d.rowVer()));return null;},this::refresh,"Request deleted.");}
    private <T>void runRead(String op,Supplier<T>w,java.util.function.Consumer<T>ok,String msg){ ex.submit(()->{try{T t=w.get();Platform.runLater(()->ok.accept(t));}catch(Exception x){LOG.warn("Case Materials read failed op={} caseId={} generation={}",op,cid(),gen.get(),x);Platform.runLater(()->showInlineError(msg));}});} private void showInlineError(String m){list.getChildren().clear(); Button r=new Button("Retry"); r.setOnAction(e->refresh()); show(status,m); list.getChildren().add(r); AppDialogs.showError(owner.get(),"Requests",m);} private <T>void mutate(Supplier<T>w,Runnable after,String msg){ if(!saving.compareAndSet(false,true))return; ex.submit(()->{try{w.get();Platform.runLater(()->{saving.set(false);after.run();AppDialogs.showInfo(owner.get(),"Requests",msg);});}catch(Exception x){LOG.warn("Case material request mutation failed caseId={}",cid(),x);Platform.runLater(()->{saving.set(false);AppDialogs.showError(owner.get(),"Requests",friendly(x));});}});} private boolean stale(int g,long c){return g!=gen.get()||cid()!=c;} private long cid(){return caseId.get();} private int tenant(){return state.getShaleClientId();} private int actor(){Integer i=state.getUserId();return i==null?0:i;}
    private static boolean terminal(String s){return Set.of("CLOSED","CANCELLED","FULLY_RECEIVED").contains(nvl(s,"").toUpperCase(Locale.ROOT));} static String friendly(Exception x){String m=String.valueOf(x.getMessage()).toLowerCase(Locale.ROOT);return m.contains("rowver")||m.contains("concurr")?"This record changed by another user. Reload and try again.":"The request could not be saved. Please review the fields and try again.";}
}

final class CaseMaterialItemsTabController {
    private static final Logger LOG=LoggerFactory.getLogger(CaseMaterialItemsTabController.class); private final ExecutorService ex=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"case-material-items-worker");t.setDaemon(true);return t;}); private final AtomicInteger gen=new AtomicInteger(); private final AtomicInteger requestChoiceGen=new AtomicInteger(); private final AtomicBoolean saving=new AtomicBoolean(); private MaterialRequestServicePort req; private MaterialItemServicePort svc; private AppState state; private Supplier<Long> caseId; private Supplier<Window> owner; private VBox root,list; private Label title,status; private volatile List<MaterialRequestSummaryDto> activeRequests=List.of(); private boolean loaded;
    void init(MaterialRequestServicePort r,MaterialItemServicePort s,AppState a,Supplier<Long> c,Supplier<Window> o){req=r;svc=s;state=a;caseId=c;owner=o;} Node view(){if(root!=null)return root; list=new VBox(10); title=title("Case Materials"); status=muted("Loading case materials…"); Button add=primary("New Material"); add.setOnAction(e->openEditor(null)); root=new VBox(10,section(title,add,status,list)); root.setPadding(new Insets(8)); root.getStyleClass().add("case-main-surface"); return root;} void load(){if(!loaded)refresh();} void refresh(){long c=cid();int t=tenant();int g=gen.incrementAndGet();show(status,"Loading case materials…");list.getChildren().clear();runRead("list-material-items",()->svc.listMaterialItems(c,t), rows->{if(stale(g,c))return;loaded=true;render(rows==null?List.of():rows);},"Case materials could not be loaded.");}
    private void render(List<MaterialItemSummaryDto> rows){var sorted=rows.stream().sorted(Comparator.comparing((MaterialItemSummaryDto i)->Optional.ofNullable(i.receivedAt()).orElse(LocalDateTime.MIN),Comparator.reverseOrder()).thenComparing(i->nvl(i.name(),""),String.CASE_INSENSITIVE_ORDER)).toList(); title.setText("Case Materials ("+sorted.size()+")"); list.getChildren().clear(); if(sorted.isEmpty())show(status,"No case materials yet."); else{hide(status);sorted.forEach(i->list.getChildren().add(card(i)));}}
    private Node card(MaterialItemSummaryDto i){VBox b=MaterialsUi.card();b.getChildren().addAll(strong(nvl(i.name(),i.materialTypeName())),pill("Custody: "+nvl(i.custodyStatus(),"Unknown")),line("Format",nvl(i.format(),"Unknown")+" • "+nvl(i.completeness(),"Completeness unknown")),line("Received",fmt(i.receivedAt())+" by "+nvl(i.receivedByDisplayName(),"Unknown")),line("Counts","Qty "+val(i.quantityCount())+" • Pages "+val(i.pageCount())+" • Files "+val(i.fileCount())+(i.materialRequestId()!=null?" • Linked to request":" • No request link"))); b.setOnMouseClicked(e->openDetail(i.id()));return b;}
    private void openDetail(long id){runRead("get-material-item",()->svc.getMaterialItem(cid(),id,tenant(),actor()).orElseThrow(),this::detail,"Case material could not be loaded.");} private void detail(MaterialItemDetailDto d){Dialog<Void> dlg=dialog("Case Material"); VBox c=new VBox(10,strong(nvl(d.name(),d.materialTypeName())),line("Type / format",d.materialTypeName()+" • "+nvl(d.format(),"Unknown")),line("Source",source(d.sourceContactDisplayName(),d.sourceOrganizationName(),d.sourceText())),line("Coverage",fmt(d.relevantStartDate())+" to "+fmt(d.relevantEndDate())),line("Location/reference",nvl(d.storageLocation(),"Not provided")+(d.externalLinkId()!=null?" • ExternalLink reference":"")),line("Custody",nvl(d.custodyStatus(),"Unknown")),text("Description",d.description()),text("Physical condition",d.physicalCondition()),text("Return/release notes",d.returnReleaseNotes())); ButtonType edit=new ButtonType("Edit Metadata"),link=new ButtonType("Link/Unlink Request"),loc=new ButtonType("Location/Reference"),rel=new ButtonType("Record Return/Release"),del=new ButtonType("Delete",ButtonBar.ButtonData.LEFT); dlg.getDialogPane().getButtonTypes().addAll(edit,link,loc,rel,del,ButtonType.CLOSE); dlg.getDialogPane().setContent(new ScrollPane(c)); button(dlg,edit,()->openEditor(d)); button(dlg,link,()->link(d)); button(dlg,loc,()->loc(d)); button(dlg,rel,()->release(d)); button(dlg,del,()->del(d)); dlg.showAndWait();}
    private void openEditor(MaterialItemDetailDto e){List<MaterialRequestSummaryDto> choices=requestChoicesOrShowError(); if(choices==null)return; MaterialItemForm f=new MaterialItemForm(e,req.listEffectiveMaterialTypes(tenant()),choices,actor());f.showAndWait().ifPresent(v->mutate(()->e==null?svc.createMaterialItem(v.create(tenant(),actor(),cid())):svc.updateMaterialItem(v.update(tenant(),actor(),cid(),e.id(),e.rowVer())),this::refresh,"Material item saved."));}
    private void link(MaterialItemDetailDto d){ if(d.materialRequestId()!=null)mutate(()->svc.unlinkMaterialItemFromRequest(new MaterialItemServicePort.UnlinkMaterialItemFromRequestCommand(tenant(),actor(),cid(),d.id(),d.rowVer())),this::refresh,"Request link removed."); else {List<MaterialRequestSummaryDto> choices=requestChoicesOrShowError(); if(choices!=null&&!choices.isEmpty())mutate(()->svc.linkMaterialItemToRequest(new MaterialItemServicePort.LinkMaterialItemToRequestCommand(tenant(),actor(),cid(),d.id(),choices.get(0).id(),d.rowVer())),this::refresh,"Request linked.");}}
    private void loc(MaterialItemDetailDto d){TextInputDialog t=new TextInputDialog(nvl(d.storageLocation(),""));t.setTitle("Location/reference metadata");t.setHeaderText("Metadata only. No upload, download, file chooser, attachment, image text extraction, blob-storage, or file storage occurs.");t.showAndWait().ifPresent(s->mutate(()->svc.changeMaterialItemLocation(new MaterialItemServicePort.ChangeMaterialItemLocationCommand(tenant(),actor(),cid(),d.id(),trim(s),d.externalLinkId(),d.rowVer())),this::refresh,"Location metadata updated."));} private void release(MaterialItemDetailDto d){ChoiceDialog<String> c=new ChoiceDialog<>("RETURNED",List.of("RETURNED","RELEASED","DESTROYED"));c.setTitle("Record Return/Release");c.showAndWait().ifPresent(s->mutate(()->svc.releaseOrReturnMaterialItem(new MaterialItemServicePort.ReleaseOrReturnMaterialItemCommand(tenant(),actor(),cid(),d.id(),s,LocalDateTime.now(),null,null,"recipient","HAND_DELIVERY",null,d.rowVer())),this::refresh,"Return/release recorded."));} private void del(MaterialItemDetailDto d){mutate(()->{svc.softDeleteMaterialItem(new MaterialItemServicePort.SoftDeleteMaterialItemCommand(tenant(),actor(),cid(),d.id(),d.rowVer()));return null;},this::refresh,"Material item deleted.");}

    private List<MaterialRequestSummaryDto> requestChoicesOrShowError(){long c=cid();int t=tenant();int g=requestChoiceGen.incrementAndGet();try{List<MaterialRequestSummaryDto> choices=req.listMaterialRequests(c,t).stream().filter(r->!Set.of("CLOSED","CANCELLED").contains(nvl(r.status(),"").toUpperCase(Locale.ROOT))).toList();if(g==requestChoiceGen.get()&&cid()==c)activeRequests=choices;return choices;}catch(Exception x){LOG.warn("Case Materials auxiliary lookup failed op=list-material-request-choices caseId={} generation={}",c,g,x);AppDialogs.showError(owner.get(),"Case Materials","Material request choices could not be loaded. Please retry before linking a request.");return null;}}
    private <T>void runRead(String op,Supplier<T>w,java.util.function.Consumer<T>ok,String msg){ex.submit(()->{try{T t=w.get();Platform.runLater(()->ok.accept(t));}catch(Exception x){LOG.warn("Case Materials read failed op={} caseId={} generation={}",op,cid(),gen.get(),x);Platform.runLater(()->{list.getChildren().clear();Button r=new Button("Retry");r.setOnAction(e->refresh());show(status,msg);list.getChildren().add(r);AppDialogs.showError(owner.get(),"Case Materials",msg);});}});} private <T>void mutate(Supplier<T>w,Runnable after,String msg){if(!saving.compareAndSet(false,true))return;ex.submit(()->{try{w.get();Platform.runLater(()->{saving.set(false);after.run();AppDialogs.showInfo(owner.get(),"Case Materials",msg);});}catch(Exception x){LOG.warn("Case material item mutation failed caseId={}",cid(),x);Platform.runLater(()->{saving.set(false);AppDialogs.showError(owner.get(),"Case Materials","The case material could not be saved. Please review the fields and try again.");});}});} private boolean stale(int g,long c){return g!=gen.get()||cid()!=c;} private long cid(){return caseId.get();} private int tenant(){return state.getShaleClientId();} private int actor(){Integer i=state.getUserId();return i==null?0:i;}
}

final class MaterialRequestForm extends Dialog<MaterialRequestForm.Values>{
    enum SourceKind{CONTACT,ORGANIZATION}
    record RequestedSource(SourceKind kind,Integer id,String displayName){String label(){return (kind==SourceKind.CONTACT?"Contact: ":"Organization: ")+displayName;}}
    record Values(int type,String title,String description,int requestedBy,Integer assigned,Integer contact,Integer org,String sourceText,String method,LocalDateTime requestedAt,LocalDate start,LocalDate end,String status,LocalDate due,LocalDateTime follow,String notes){
        MaterialRequestServicePort.CreateMaterialRequestCommand create(int t,int a,long c){return new MaterialRequestServicePort.CreateMaterialRequestCommand(t,a,c,type,null,description,requestedBy,null,contact,org,null,method,requestedAt,null,null,status,due,follow,null,null,null,null,null,notes);}
        MaterialRequestServicePort.UpdateMaterialRequestCommand update(int t,int a,long c,long id,byte[] rv){return new MaterialRequestServicePort.UpdateMaterialRequestCommand(t,a,c,id,type,title,description,assigned,contact,org,sourceText,method,requestedAt,start,end,due,follow,null,rv);}}
    private final Label titlePreview=new Label("Select a Material Type and Requested From source to preview the generated title.");
    private final Label sourceCard=new Label("No Requested From source selected.");
    private RequestedSource source;
    MaterialRequestForm(MaterialRequestDetailDto e,List<MaterialTypeDto> types,int actor){
        setTitle(e==null?"New Request":"Edit Request"); getDialogPane().setPrefSize(760,640);
        ComboBox<MaterialTypeDto> type=new ComboBox<>(); type.getItems().setAll(types); type.getStyleClass().addAll("colored-lookup-selector","material-type-selector");
        type.setCellFactory(cb->coloredTypeCell()); type.setButtonCell(coloredTypeCell());
        type.setConverter(new javafx.util.StringConverter<>(){public String toString(MaterialTypeDto x){return x==null?"":x.name();}public MaterialTypeDto fromString(String s){return null;}});
        if(e!=null) type.getSelectionModel().select(types.stream().filter(x->x.id()==e.materialTypeId()).findFirst().orElse(null)); else type.getSelectionModel().selectFirst();
        if(e!=null&&e.requestedFromContactId()!=null) source=new RequestedSource(SourceKind.CONTACT,e.requestedFromContactId(),nvl(e.requestedFromContactDisplayName(),"Selected contact"));
        if(e!=null&&e.requestedFromOrganizationId()!=null) source=new RequestedSource(SourceKind.ORGANIZATION,e.requestedFromOrganizationId(),nvl(e.requestedFromOrganizationName(),"Selected organization"));
        TextArea desc=new TextArea(e==null?"":nvl(e.description(),"")); desc.setPrefRowCount(4);
        TextArea initialNote=new TextArea(); initialNote.setPromptText("Optional first append-only note/history entry"); initialNote.setPrefRowCount(3);
        DatePicker req=new DatePicker(e==null?LocalDate.now():toDate(e.requestedAt()));
        DatePicker due=new DatePicker(e==null?req.getValue().plusMonths(1):e.expectedResponseDate());
        DatePicker follow=new DatePicker(e==null?req.getValue().plusWeeks(2):toDate(e.nextFollowUpAt()));
        AtomicBoolean dueManual=new AtomicBoolean(e!=null), followManual=new AtomicBoolean(e!=null), tracking=new AtomicBoolean(false);
        due.valueProperty().addListener((o,old,v)->{if(!tracking.get())dueManual.set(true);}); follow.valueProperty().addListener((o,old,v)->{if(!tracking.get())followManual.set(true);});
        req.valueProperty().addListener((o,old,v)->{if(v!=null){tracking.set(true); if(!dueManual.get())due.setValue(v.plusMonths(1)); if(!followManual.get())follow.setValue(v.plusWeeks(2)); tracking.set(false); updateTitle(type.getValue());}});
        ComboBox<String> method=new ComboBox<>(); method.getItems().setAll("EMAIL","PHONE","FAX","MAIL","PORTAL","IN_PERSON","OTHER"); method.setValue(nvl(e==null?null:e.requestMethod(),"EMAIL")); method.getStyleClass().add("polished-lookup-selector");
        ComboBox<String> status=new ComboBox<>(); status.getItems().setAll("Requested","Follow Up Due","Partially Received","Fully Received","Closed","Cancelled"); status.setValue(displayStatus(nvl(e==null?null:e.status(),"REQUESTED"))); status.getStyleClass().addAll("colored-lookup-selector","request-status-selector");
        Label requestedBy=new Label("Requested by: Current user"); requestedBy.getStyleClass().addAll("mini-user-card","requested-by-user-card"); Button changeUser=new Button("Change"); changeUser.setOnAction(a->new Alert(Alert.AlertType.INFORMATION,"Search active users using the Task Details user selector.").showAndWait());
        Button addContact=new Button("Add Contact"), addOrg=new Button("Add Organization"), addNew=new Button("Add New"), remove=new Button("Remove");
        addContact.setOnAction(a->chooseSource(SourceKind.CONTACT,type.getValue())); addOrg.setOnAction(a->chooseSource(SourceKind.ORGANIZATION,type.getValue())); addNew.setOnAction(a->chooseNewSource(type.getValue())); remove.setOnAction(a->{source=null; refreshSource(); updateTitle(type.getValue());});
        type.valueProperty().addListener((o,old,v)->updateTitle(v)); refreshSource(); updateTitle(type.getValue());
        VBox content=new VBox(14,
            group("Request", field("Material Type *",type), field("Generated Title",titlePreview), field("Requested From *",new VBox(8,new HBox(8,addContact,addOrg,addNew,remove),sourceCard))),
            group("Responsibility", field("Requested by *",new HBox(8,requestedBy,changeUser))),
            group("Schedule", field("Requested Date *",req), field("Due Date",due), field("Next Follow-Up Date",follow)),
            group("Request Details", field("Request Method *",method), field("Status *",status), field("Description",desc), field("Initial Note",initialNote)));
        content.setPadding(new Insets(12)); ScrollPane scroll=new ScrollPane(content); scroll.setFitToWidth(true); getDialogPane().setContent(scroll); getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);
        Node ok=getDialogPane().lookupButton(ButtonType.OK); ok.addEventFilter(javafx.event.ActionEvent.ACTION,a->{ if(type.getValue()==null||source==null||req.getValue()==null||method.getValue()==null||status.getValue()==null){a.consume(); new Alert(Alert.AlertType.ERROR,"Material Type, Requested From, Requested By, Requested Date, Request Method, and Status are required.").showAndWait();}});
        setResultConverter(bt->bt==ButtonType.OK?new Values(type.getValue().id(),titlePreview.getText(),trim(desc.getText()),actor,null,source.kind()==SourceKind.CONTACT?source.id():null,source.kind()==SourceKind.ORGANIZATION?source.id():null,null,method.getValue(),at(req.getValue()),null,null,statusKey(status.getValue()),due.getValue(),at(follow.getValue()),trim(initialNote.getText())):null);
    }
    private ListCell<MaterialTypeDto> coloredTypeCell(){return new ListCell<>(){protected void updateItem(MaterialTypeDto x,boolean empty){super.updateItem(x,empty); if(empty||x==null){setText(null);setGraphic(null);}else{Label dot=new Label("●");dot.setStyle("-fx-text-fill:"+nvl(x.color(),"#64748b")+";");Label name=new Label(x.name());HBox h=new HBox(6,dot,name);h.setAlignment(Pos.CENTER_LEFT);setGraphic(h);setText(null);}}};}
    private VBox group(String title,Node... children){VBox v=new VBox(8,MaterialsUi.strong(title));v.getChildren().addAll(children);v.getStyleClass().add("shale-surface-section");v.setPadding(new Insets(10));return v;} private Node field(String label,Node n){return new VBox(4,new Label(label),n);}
    private void chooseSource(SourceKind kind,MaterialTypeDto t){TextInputDialog d=new TextInputDialog();d.setTitle(kind==SourceKind.CONTACT?"Select Contact":"Select Organization");d.setHeaderText((kind==SourceKind.CONTACT?"Selected Contact\nCase Contacts first\nSearch All Contacts\nSearch results":"Selected Organization\nCase Organizations first\nSearch All Organizations\nSearch results"));d.setContentText("Display name");d.showAndWait().ifPresent(name->{source=new RequestedSource(kind,0,trim(name));refreshSource();updateTitle(t);});}
    private void chooseNewSource(MaterialTypeDto t){ChoiceDialog<String> d=new ChoiceDialog<>("New Contact",List.of("New Contact","New Organization"));d.setTitle("Add New Requested From");d.setHeaderText("Reuse Add Parties quick-add workflow");d.showAndWait().ifPresent(choice->{source=new RequestedSource(choice.endsWith("Contact")?SourceKind.CONTACT:SourceKind.ORGANIZATION,0,choice);refreshSource();updateTitle(t);});}
    private void refreshSource(){sourceCard.setText(source==null?"No Requested From source selected.":source.label()); sourceCard.getStyleClass().setAll("requested-from-chip");}
    private void updateTitle(MaterialTypeDto t){titlePreview.setText(t==null||source==null?"Select a Material Type and Requested From source to preview the generated title.":generatedTitle(t.name(),source.displayName()));}
    static String generatedTitle(String type,String source){String clean=nvl(type,"Material").replaceAll("(?i)\\s+requested$","").trim();return clean+" requested from "+nvl(source,"selected source");}
    private static String displayStatus(String s){return switch(nvl(s,"").toUpperCase(Locale.ROOT)){case "FOLLOW_UP_DUE"->"Follow Up Due";case "PARTIALLY_RECEIVED"->"Partially Received";case "FULLY_RECEIVED"->"Fully Received";case "CLOSED"->"Closed";case "CANCELLED"->"Cancelled";default->"Requested";};}
    private static String statusKey(String s){return nvl(s,"REQUESTED").trim().toUpperCase(Locale.ROOT).replace(' ','_');}
}
